    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "supported",
      "reason": "The bicycle definition contains no rail exclusion, and any on-track equipment satisfying its admitting clauses also satisfies the quoted ru.bicycle contract."
    },
    {
      "class": "ru.school_bus",
      "verdict": "supported",
      "reason": "School designation and markings do not prohibit additional human propulsion, and every admitted school bus also carries ru.bicycle under the quoted contract."
    },
    {
      "class": "ru.taxicab",
      "verdict": "supported",
      "reason": "Passenger-for-hire service and markings do not independently admit a taxicab, while any member satisfying the bicycle clauses also carries ru.bicycle."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "supported",
      "reason": "Neither branch of the contract defeats coverage because every member admitted by the bicycle clauses must also satisfy the quoted ru.bicycle contract."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "supported",
      "reason": "Being drawn or forming a combination supplies no separate admission, and any such member satisfying the bicycle clauses also carries ru.bicycle."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "supported",
      "reason": "Transit service and identifying displays do not prohibit additional human propulsion, and every admitted member also satisfies the quoted ru.bicycle contract."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "A goods-carrying body and motor propulsion do not prohibit additional human propulsion, and every truck admitted by the bicycle clauses also carries ru.bicycle."
    }
  ]
}

